package org.localscape.nylocas.mage;
import org.junit.Test;
import org.localscape.nylocas.mage.MageStrategy.*;
import static org.junit.Assert.*;
public class MageEightTenBlueThroughputTest {
 private final MageStrategy s=new MageStrategy();private final Room r=new Room();private int key;
 private Crab add(int wave,int born,Lane lane,boolean big,Style style,int x,int y){Crab c=new Crab(++key,key,born,wave,lane,'W',big,style,MageStrategy.tile(x,y));c.pendingDamage=0;r.crabs.add(c);return c;}
 private void west8(){r.wave=8;r.spawns[8]=52;r.ready=55;r.player=MageStrategy.tile(3290,4249);Crab p=new Crab(100,100,52,8,Lane.WEST,'S',true,Style.MAGIC,MageStrategy.tile(3281,4248));s.attacked(new Decision(p,Weapon.EYE,r.player,false,"West big 8","West big 8"),55,52);}
 private Crab entry(){west8();Crab p=add(7,40,Lane.SOUTH,true,Style.RANGE,3295,4242);p.hp=0;p.dying=true;p.observeRemovalAt(55);s.decide(r,53);r.crabs.clear();r.player=MageStrategy.tile(3294,4245);Crab a=add(8,54,Lane.SPLIT,false,Style.MAGIC,3301,4245);add(8,54,Lane.SPLIT,false,Style.MAGIC,3301,4247);Crab m=add(8,55,Lane.SPLIT,false,Style.MELEE,3295,4241);m.observePosition(MageStrategy.tile(3295,4242));add(8,55,Lane.SPLIT,false,Style.MELEE,3296,4243);return a;}
 @Test public void seed55293390024858UsesAReadyBlueBeforeRunningUnderTheIncomingMelee(){Crab blue=entry();assertSame(blue,s.decide(r,55).target);}
 @Test public void twoObservedBlueChildrenCanUseConsecutiveThreeTickShots(){Crab first=entry();Decision d=s.decide(r,55);s.attacked(d,58,55);first.pendingDamage=8;r.ready=58;r.player=MageStrategy.tile(3298,4247);Crab second=r.crabs.get(1);second.observePosition(MageStrategy.tile(3301,4248));Decision next=s.decide(r,58);assertSame(second,next.target);assertEquals(Weapon.EYE,next.weapon);}
 @Test public void finishesAVisibleLowRollBeforeOpeningTheOtherBlue(){Crab first=entry();Decision d=s.decide(r,55);s.attacked(d,58,55);first.hp=4;r.ready=58;r.player=MageStrategy.tile(3298,4247);assertSame(first,s.decide(r,59).target);}
 @Test public void keepsTheMandatoryWestEightSurvivingRetry(){entry();Crab p=add(8,52,Lane.WEST,true,Style.MAGIC,3284,4248);p.hp=4;s.attacked(new Decision(p,Weapon.EYE,r.player,false,"West big 8","West big 8"),55,52);r.player=MageStrategy.tile(3290,4249);assertSame(p,s.decide(r,55).target);}
 @Test public void newWaveNineMagicCompetesWithOlderTrackedMelee(){west8();r.wave=9;r.spawns[9]=56;r.ready=62;r.player=MageStrategy.tile(3293,4248);add(8,54,Lane.SPLIT,false,Style.MELEE,3294,4251);Crab blue=add(9,61,Lane.SPLIT,false,Style.MAGIC,3294,4244);assertSame(blue,s.decide(r,62).target);}
 private Crab ten(int magicX,int magicY){west8();r.wave=10;r.spawns[10]=68;r.ready=70;r.player=MageStrategy.tile(3296,4248);Crab blue=add(9,66,Lane.SPLIT,false,Style.MAGIC,magicX,magicY);for(int i=0;i<10;i++)add(10,68,Lane.SOUTH,false,Style.RANGE,3296,4238);blue.hp=3;s.attacked(new Decision(blue,Weapon.EYE,r.player,false,null,"low roll"),70,67);return blue;}
 @Test public void actualTenTakesTheCardinalMeleeThatCanReleaseBeforeEleven(){ten(3293,4253);Crab melee=add(9,65,Lane.SPLIT,false,Style.MELEE,3297,4248);assertSame(melee,s.decide(r,70).target);}
 @Test public void actualTenStillFinishesANearBlueThatCanReleaseBeforeEleven(){Crab blue=ten(3295,4248);add(9,65,Lane.SPLIT,false,Style.MELEE,3296,4249);assertSame(blue,s.decide(r,70).target);}
 @Test public void cooldownStagesForTheObservedMovingBlueRatherThanItsOldSquare(){west8();r.wave=9;r.spawns[9]=56;r.ready=65;r.player=MageStrategy.tile(3294,4248);Crab blue=add(9,62,Lane.SPLIT,false,Style.MAGIC,3297,4248);blue.observePosition(MageStrategy.tile(3298,4248));Decision d=s.decide(r,63);assertNull(d.target);assertEquals(MageStrategy.tile(3298,4248),d.tile);assertTrue(d.reason,d.reason.startsWith("Stage beside observed pre-ten magic"));}

 @Test public void seed55293390024862ChoosesTheCardinalSiblingBeforeTheElevenCheck(){west8();r.wave=10;r.spawns[10]=68;r.ready=70;r.player=MageStrategy.tile(3295,4247);Crab blue=add(9,63,Lane.SPLIT,false,Style.MAGIC,3291,4246);blue.observePosition(MageStrategy.tile(3292,4245));s.attacked(new Decision(blue,Weapon.EYE,r.player,false,null,"visible zero roll"),70,67);Crab melee=add(9,63,Lane.SPLIT,false,Style.MELEE,3293,4248);melee.observePosition(MageStrategy.tile(3294,4247));for(int i=0;i<10;i++)add(10,68,Lane.SOUTH,false,Style.RANGE,3296,4238);Decision d=s.decide(r,70);assertSame(d.reason+" key="+(d.target==null?-1:d.target.key),melee,d.target);}

 @Test public void aSettledPillarBlockerRetainsItsSetupPriority(){west8();r.wave=10;r.spawns[10]=68;r.ready=70;r.player=MageStrategy.tile(3295,4247);Crab blue=add(9,63,Lane.SPLIT,false,Style.MAGIC,3292,4245);s.attacked(new Decision(blue,Weapon.EYE,r.player,false,null,"visible zero roll"),70,67);add(9,63,Lane.SPLIT,false,Style.MELEE,3294,4247);for(int i=0;i<10;i++)add(10,68,Lane.SOUTH,false,Style.RANGE,3296,4238);assertSame(blue,s.decide(r,70).target);}
}
